def is_good_triple(x, y, z):
    numerator = (x + 1)**y
    denominator = x**z + 1
    # Since x, y, z are positive, both are positive. We check for integer divisibility.
    if numerator % denominator == 0:
        return True
    return False

results = []
for x in range(1, 5):
    for y in range(1, 5):
        for z in range(1, 5):
            if is_good_triple(x, y, z):
                results.append((x, y, z))

print("Good Triples Found:")
for triple in results:
    print(triple)
print(f"\nTotal Count: {len(results)}")

def is_power_of_3(n):
    if n <= 0:
        return False
    while n > 1:
        if n % 3 != 0:
            return False
        n //= 3
    return True

zs_to_check = [5, 7, 9]
results = {}

for z in zs_to_check:
    val = 2**z + 1
    is_power = is_power_of_3(val)
    results[z] = val
    print(f"z={z}: 2^{z}+1 = {val}. Is it a power of 3? {is_power}")

def calculate_K(x):
    # K = x^4 - x^3 + x^2 - x + 1
    return x**4 - x**3 + x**2 - x + 1

def check_power_of_5(n):
    if n <= 0:
        return False
    if n == 1:
        return True
    while n % 5 == 0:
        n //= 5
    return n == 1

solutions = []
# We check x from 2 up to 99 (since x=1 results in K=1=5^0)
for x in range(2, 100):
    K = calculate_K(x)
    if check_power_of_5(K):
        solutions.append(x)

print("Values of x (x >= 2) such that K is a power of 5:", solutions)
